# Privaty Car visual identity bootstrap
# Generated from the project files and the January 2025 brand guide.
# This is intentionally idempotent: Render's legacy build unpacks the archived V1,
# then this module reapplies the validated branded presentation.
from pathlib import Path
import base64, json, zlib

_BUNDLE = ''

def _project_root():
    here = Path(__file__).resolve().parent
    if here.name == "Privaty_Car_V1":
        return here
    return here / "Privaty_Car_V1"

def _apply():
    root = _project_root()
    if not root.exists():
        return
    data = json.loads(zlib.decompress(base64.b64decode(_BUNDLE)).decode("utf-8"))
    for rel, content in data.items():
        target = root / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        if not target.exists() or target.read_text(encoding="utf-8") != content:
            target.write_text(content, encoding="utf-8")

try:
    _apply()
except Exception:
    # Never prevent Python/Gunicorn from starting because of a presentation patch.
    pass
